  const clean={...p}; delete clean.label;
  const sim=createSim(clean);
  let peakB=0,peakR=0, samples=[], extinctAt=null
  for(let t=0;t<secs;t+=0.05){ stepSim(sim,clean,0.05); const b=sim.blobs.filter(x=>x.type==='blue').length,r=sim.blobs.length-b; if(b===0&&extinctAt===null)extinctAt=Math.round(t); if(t%20<0.05){peakB=Math.max(peakB,b);peakR=Math.max(peakR,r); samples.push(Math.round(t)+':B'+b+'/R'+r)} }
